import {createWarCostume} from './wars3d-details.js';
import {warActorOffset} from './wars3d-poses.js';
import {soldierRig} from './wars3d-rig.js';
import {createWarEnvironment} from './wars3d-environment.js';
import {createActorFactory} from './3d/actors.js';
import {create3DEffects} from './3d/effects.js';
import {createWarEquipment,makeArrow} from './wars3d-equipment.js';
import {DEFEAT_TIMING,defeatOpacity} from './wars3d-weapons.js';
export async function createWarScene(runtime,model,{onEvent=()=>{}}={}){const{B,scene}=runtime,factory=await createActorFactory(runtime,soldierRig),effects=create3DEffects(runtime,{onEvent}),actors=new Map(),retired=new Set(),projectiles=new Map(),materials=new Map(),props=[];let currentItems='',lastEvents=0;
 function mat(name,color,emissive=0){if(materials.has(name))return materials.get(name);const m=new B.StandardMaterial(name,scene);m.diffuseColor=B.Color3.FromHexString(color);m.specularColor=new B.Color3(.06,.06,.06);if(emissive)m.emissiveColor=m.diffuseColor.scale(emissive);materials.set(name,m);return m;}
 const {zoneMeshes}=createWarEnvironment(runtime,model,mat);
 const propContainers=Object.fromEntries(await Promise.all(['pony','dragon','cannon'].map(async name=>[name,await runtime.assets.load('assets/wars3d/'+name+'.glb')])));
 function makeProp(name,u){const entry=propContainers[name].instantiateModelsToScene(n=>'unit'+u.id+':'+n,false,{doNotInstantiate:true}),root=new B.TransformNode('mount-'+u.id,scene),nodes={};for(const n of entry.rootNodes)n.parent=root;for(const n of root.getDescendants()){const key=n.name.split(':').at(-1);nodes[key]=n;if(n.getTotalVertices?.()){n.isPickable=false;n.receiveShadows=true;runtime.shadows?.addShadowCaster(n);if(n.material?.name==='team')n.material=mat('propteam'+u.side,u.side?'#e65f53':'#398ee2');}}let barrel=null;if(name==='cannon'){barrel=new B.TransformNode('cannon-barrel:'+u.id,scene);barrel.parent=root;barrel.position.set(0,.785,-.1);for(const n of Object.values(nodes))if(n.getTotalVertices?.()&&['steel','gold','dark'].includes(n.material?.name)){n.parent=barrel;n.position.set(0,-.785,.1);}}return{root,nodes,entry,barrel};}
 function addActor(u){const actor=factory.create(u),equipment=createWarEquipment(runtime,actor,u,mat,u.weaponOverride||{}),prop=['lancer','dragon','cannon'].includes(u.type)?makeProp(u.type==='lancer'?'pony':u.type,u):null;const costume=createWarCostume(runtime,actor,u,mat);const bar=B.MeshBuilder.CreatePlane('health',{width:.75,height:.065},scene);bar.billboardMode=B.Mesh.BILLBOARDMODE_ALL;bar.material=mat('hp'+u.side,u.side?'#ec7770':'#7de7b4',.3);bar.material.backFaceCulling=false;bar.isPickable=false;const selection=B.MeshBuilder.CreateTorus('owner-ring',{diameter:.85,thickness:.055,tessellation:16},scene);selection.material=mat('ring'+u.side,u.side?'#ff9c77':'#80cafa',.3);selection.position.y=.035;if(['wizard','ice','fire','healer'].includes(u.type)){const hat=B.MeshBuilder.CreateCylinder('mage-hat',{height:.7,diameterBottom:.65,diameterTop:0,tessellation:6},scene);hat.parent=actor.nodes.head;hat.position.y=.57;hat.material=mat('magehat'+u.type,{ice:'#91cfe8',fire:'#d76443',healer:'#7fad75',wizard:'#a98bc0'}[u.type]);}if(['golem','slime'].includes(u.type))for(const mesh of actor.meshes){const old=mesh.material;if(!old)continue;const key='class-'+u.type+'-'+old.name;if(!materials.has(key)){const m=old.clone(key);if(m.albedoColor)m.albedoColor=B.Color3.FromHexString(u.type==='golem'?'#8d9991':'#94ba75');materials.set(key,m);}mesh.material=materials.get(key);}const healthBack=B.MeshBuilder.CreatePlane('health-back',{width:.82,height:.11},scene);healthBack.billboardMode=B.Mesh.BILLBOARDMODE_ALL;bar.parent=healthBack;bar.billboardMode=B.Mesh.BILLBOARDMODE_NONE;healthBack.material=mat('health-back','#263c3b');healthBack.isPickable=false;selection.isPickable=false;actors.set(u.id,{actor,equipment,costume,prop,bar,healthBack,selection,dead:false,down:false});return actors.get(u.id);}
 function updateActor(u,dt){const a=actors.get(u.id)||addActor(u);if(!u.alive&&!a.dead){a.actor.endRagdoll();a.dead=true;a.deathAge=0;}const deathAge=u.alive?0:(a.deathAge=(a.deathAge||0)+Math.max(0,dt)),offset=warActorOffset(u,deathAge),state={...u,x:u.x+offset.x*Math.cos(u.angle)+offset.z*Math.sin(u.angle),z:u.z-offset.x*Math.sin(u.angle)+offset.z*Math.cos(u.angle),y:offset.y,mounted:['lancer','dragon'].includes(u.type),recover:u.state==='recover',clock:model.clock,deathAge,block:model.clock<u.blockUntil};
 a.actor.update(state,dt);
 if(u.alive&&u.state==='down'&&!a.down){a.actor.knockdown({x:u.vx||1,y:2,z:u.vz||0});a.down=true;}if(u.alive&&u.state==='recover')a.down=false;
 const opacity=u.alive?1:defeatOpacity(deathAge);a.costume.update({...u,opacity},model.phase==='build'?0:dt);for(const mesh of a.actor.meshes)mesh.visibility=opacity;a.equipment.update({...u,mounted:state.mounted,clock:model.clock,deathAge,block:state.block});
 if(a.prop){a.prop.root.position.set(u.x,0,u.z);a.prop.root.scaling.setAll(u.scale);a.prop.root.rotation.y=u.angle+(u.type==='dragon'?(u.aimYaw||0):0);if(a.prop.barrel){a.prop.barrel.rotation.x=-(u.aimPitch||0);a.prop.barrel.rotation.y=u.aimYaw||0;}for(const m of a.prop.root.getDescendants())if(m.getTotalVertices)m.visibility=opacity;const moving=u.state==='walk'||u.state==='run';for(const [name,n]of Object.entries(a.prop.nodes)){if(name.startsWith('leg')){const sign=['legFL','legBR'].includes(name)?1:-1;n.rotation.x=moving?Math.sin(u.walk||0)*.45*sign:0;n.rotationQuaternion=null;}if(name.startsWith('wing')){n.rotationQuaternion=null;n.rotation.z=Math.sin(model.clock*4)*.22*(name==='wingL'?1:-1);}if(name.startsWith('wheel')){n.rotationQuaternion=null;n.rotation.x=-(u.traveled||0)/.32;}}}a.bar.position.set(0,0,-.01);a.bar.scaling.x=Math.max(.001,Math.min(1,u.hp/u.maxHP));a.healthBack.position.set(u.x,2.45*u.scale,u.z);a.healthBack.setEnabled(u.alive&&model.phase!=='build');a.bar.setEnabled(u.alive&&model.phase!=='build');a.selection.scaling.setAll(u.scale*(['lancer','dragon'].includes(u.type)?1.5:1));a.selection.position.x=u.x;a.selection.position.z=u.z;a.selection.setEnabled(u.alive);if(!u.alive&&deathAge>DEFEAT_TIMING.remove){a.prop?.entry.dispose();a.prop?.root.dispose();a.costume.dispose();a.equipment.dispose();a.actor.dispose();a.bar.dispose();a.healthBack.dispose();a.selection.dispose();actors.delete(u.id);retired.add(u.id);}}
 function updateProjectiles(){const ids=new Set();for(const p of model.projectiles){ids.add(p.id);let m=projectiles.get(p.id);if(!m){m=new B.TransformNode('projectile-'+p.id,scene);if(p.kind==='arrow'){const arrow=makeArrow(runtime,mat('arrow','#b69758'),'flying-arrow');arrow.parent=m;for(const child of arrow.getChildren())child.position.z-=.68;}else{const ball=B.MeshBuilder.CreatePolyhedron(p.kind,{type:1,size:p.kind==='shell'?.19:.12},scene);ball.material=mat('projectile-'+p.kind,{shell:'#404858',stone:'#aaa38d',ice:'#9feeff',fire:'#ffad58',heal:'#7aef9c',pulse:'#65f6f2'}[p.kind]||'#d1a0ff',.5);ball.parent=m;}projectiles.set(p.id,m);}m.position.set(p.x,p.y,p.z);m.rotationQuaternion=B.Quaternion.RotationYawPitchRoll(Math.atan2(p.vx,p.vz),-Math.atan2(p.vy,Math.hypot(p.vx,p.vz)),0);}for(const[id,m]of projectiles)if(!ids.has(id)){m.dispose();projectiles.delete(id);}}
 return{factory,effects,getActor:id=>actors.get(id),update(dt){zoneMeshes.forEach(m=>m.setEnabled(model.phase==='build'));if(model.phase==='build'){const rows=[...model.items,...(!['sandbox','versus'].includes(model.mode)?model.enemy.map((b,i)=>({type:b.type,x:(b.x-500)/40,z:(b.y-320)/40,side:1,id:-i-1})):[])],ids=new Set(rows.map(r=>r.id));for(const [id,a]of actors)if(!ids.has(id)){a.prop?.entry.dispose();a.prop?.root.dispose();a.costume.dispose();a.equipment.dispose();a.actor.dispose();a.bar.dispose();a.healthBack.dispose();a.selection.dispose();actors.delete(id);}for(const row of rows){const p=model.spec(row.type);updateActor({...p,...row,scale:['giant','golem'].includes(row.type)?1.4:row.type==='slime'?.8:1,alive:true,state:'idle',angle:row.side?-Math.PI/2:Math.PI/2,hp:p.hp,maxHP:p.hp},dt||.016);}}else for(const u of model.units){if(retired.has(u.id))continue;updateActor(u,dt);}updateProjectiles();while(model.events.length){const e=model.events.shift();effects.event(e);}effects.update(dt);},clearDeployment(){for(const a of actors.values()){a.prop?.entry.dispose();a.prop?.root.dispose();a.costume.dispose();a.equipment.dispose();a.actor.dispose();a.bar.dispose();a.healthBack.dispose();a.selection.dispose();}actors.clear();retired.clear();},refreshShadows(){for(const a of actors.values())a.actor.shadows();},dispose(){for(const a of actors.values()){a.prop?.entry.dispose();a.prop?.root.dispose();a.costume.dispose();a.equipment.dispose();a.actor.dispose();a.bar.dispose();a.healthBack.dispose();a.selection.dispose();}for(const m of projectiles.values())m.dispose();factory.dispose();effects.dispose();}};
}
